\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',message;end if;end $$;
create function pg_temp.assert_denied(statement text) returns void language plpgsql as $$ begin begin execute statement;exception when others then return;end;raise exception 'FAIL: statement was allowed: %',statement;end $$;
create function pg_temp.video_command() returns jsonb language sql as $$ select '{"type":"attachVideo","topicId":"math-002","video":{"id":"test-video","title":"Числовой луч","fileName":"lesson.mp4","mimeType":"video/mp4","size":1024,"storage":"supabase","storageKey":"00000000-0000-4000-8000-000000000003/math-002/test-video.mp4","uploadedBy":"00000000-0000-4000-8000-000000000003","uploadedAt":"2026-09-24T00:00:00.000Z"}}'::jsonb $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_denied('select public.learning_command(pg_temp.video_command())');
select pg_temp.assert_denied($q$insert into storage.objects(bucket_id,name,owner_id,metadata) values('lesson-videos','00000000-0000-4000-8000-000000000001/math-002/student.mp4',auth.uid()::text,'{}')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_denied('select public.learning_command(pg_temp.video_command())');
select pg_temp.assert_denied($q$insert into storage.objects(bucket_id,name,owner_id,metadata) values('lesson-videos','00000000-0000-4000-8000-000000000004/math-002/spoof.mp4',auth.uid()::text,'{}')$q$);
insert into storage.objects(bucket_id,name,owner_id,metadata) values('lesson-videos','00000000-0000-4000-8000-000000000003/math-002/test-video.mp4',auth.uid()::text,'{"size":1024,"mimetype":"video/mp4"}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=0 from storage.objects),'unattached video private');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_denied($q$select public.learning_command(jsonb_set(pg_temp.video_command(),'{video,size}','999'))$q$);
select public.learning_command(pg_temp.video_command());
select public.learning_command(pg_temp.video_command());
select pg_temp.assert_true((select jsonb_array_length(content->'videos')=1 from public.topics where id='math-002'),'upload publication idempotent');
select pg_temp.assert_true((select count(*)=1 from public.topics where id='math-002' and content->>'order'='2'),'PDF topic mapping');
with removed as (delete from storage.objects returning *) select pg_temp.assert_true((select count(*)=0 from removed),'published files cannot be removed');
with changed as (update storage.objects set metadata='{}' returning *) select pg_temp.assert_true((select count(*)=0 from changed),'published files cannot be overwritten');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=1 from storage.objects),'active student can watch published video');
select public.learning_command('{"type":"saveActivity","activity":{"id":"00000000-0000-4000-8000-000000000301","studentId":"00000000-0000-4000-8000-000000000001","topicId":"math-002","stage":"lesson","answers":{},"questionIds":[],"attemptId":"00000000-0000-4000-8000-000000000302","videoSeconds":0}}');
select public.learning_command('{"type":"saveVideoPosition","studentId":"00000000-0000-4000-8000-000000000001","topicId":"math-002","videoId":"test-video","seconds":12.5}');
select pg_temp.assert_denied($q$select public.learning_command('{"type":"saveVideoPosition","studentId":"00000000-0000-4000-8000-000000000002","topicId":"math-002","videoId":"test-video","seconds":20}')$q$);
select public.learning_command('{"type":"saveActivity","activity":{"id":"00000000-0000-4000-8000-000000000301","studentId":"00000000-0000-4000-8000-000000000001","topicId":"math-002","stage":"lesson","answers":{},"questionIds":[],"attemptId":"00000000-0000-4000-8000-000000000302","videoSeconds":0}}');
select pg_temp.assert_true((select payload#>>'{videoPositions,test-video}'='12.5' from public.activities where topic_id='math-002'),'position survives lesson state saves');
select pg_temp.assert_true((select count(*)=0 from public.attempts),'video never creates skill evidence');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select public.learning_command(jsonb_build_object('type','saveTopic','topic',(select content||'{"lesson":"Объяснение","objective":"Понимаем числа","example":"2 меньше 3"}'::jsonb from public.topics where id='math-002')));
select pg_temp.assert_true((select jsonb_array_length(content->'videos')=1 from public.topics where id='math-002'),'content edit preserves videos');
select public.learning_command('{"type":"saveProfile","profile":{"id":"00000000-0000-4000-8000-000000000001","name":"Алексей","role":"student","active":false}}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=0 from storage.objects),'disabled student loses video access');
rollback;
